class NaiveSnake {
    List<int[]> body = new ArrayList<>(); // tail at 0, head at end
    int[][] food; int foodIdx = 0; int W, H;
    NaiveSnake(int w, int h, int[][] f) { W=w; H=h; food=f; body.add(new int[]{0,0}); }
    int move(String d) {
        int[] head = body.get(body.size()-1);
        int r = head[0], c = head[1];
        if (d.equals("U")) r--; else if (d.equals("D")) r++;
        else if (d.equals("L")) c--; else c++;
        if (r<0||r>=H||c<0||c>=W) return -1;
        // O(L) scan — the killer
        for (int[] b : body) if (b[0]==r && b[1]==c) {
            // BUG: also forbids legal move into vacating tail
            return -1;
        }
        body.add(new int[]{r,c});
        if (foodIdx < food.length && food[foodIdx][0]==r && food[foodIdx][1]==c) {
            foodIdx++; // grow: keep tail
        } else {
            body.remove(0); // O(L) shift on ArrayList
        }
        return foodIdx;
    }
}

