import java.util.*;

public class SnakeGame {
    private final int width, height;
    private final int[][] food;
    private int foodIdx = 0;
    private int score = 0;
    private boolean over = false;

    // Invariant: deque and set always contain exactly the same ids.
    private final Deque<Integer> body = new ArrayDeque<>(); // head at front
    private final Set<Integer> occupied = new HashSet<>();

    public SnakeGame(int width, int height, int[][] food) {
        this.width = width; this.height = height;
        this.food = food == null ? new int[0][] : food;
        body.offerFirst(encode(0, 0));
        occupied.add(encode(0, 0));
    }

    private int encode(int r, int c) { return r * width + c; }

    public int move(String dir) {
        if (over) return -1;
        int head = body.peekFirst();
        int r = head / width, c = head % width;
        switch (dir) {
            case "U": r--; break;
            case "D": r++; break;
            case "L": c--; break;
            case "R": c++; break;
            default: return score; // ignore illegal input, don't kill game
        }
        if (r < 0 || r >= height || c < 0 || c >= width) {
            over = true; return -1;
        }
        int next = encode(r, c);
        boolean eating = foodIdx < food.length
                && food[foodIdx][0] == r && food[foodIdx][1] == c;
        if (!eating) {
            // Tail vacates first: legal to move into old tail.
            int tail = body.pollLast();
            occupied.remove(tail);
        }
        if (occupied.contains(next)) {
            over = true; return -1;
        }
        body.offerFirst(next);
        occupied.add(next);
        if (eating) { foodIdx++; score++; }
        return score;
    }

    public int getScore() { return score; }
    public boolean isOver() { return over; }
}
